/* From Uiverse.io by joe-herbert  - Tags: minimalist, card, hover, animated, curtains */
/*Card design*/
.__UIV_SCOPE__ .card {
  width: 200px;
  height: 300px;
  background: lightgray;
  box-shadow: 0 4px 35px rgba(0, 0, 0, 0.2);
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ .card > .child {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  transition: clip-path 0.6s;
  z-index: 1;
}

.__UIV_SCOPE__ .card .card-1 {
  clip-path: polygon(0% 0%, 75% 0%, 0% 75%);
}

.__UIV_SCOPE__ .card .card-1:hover {
  clip-path: polygon(0% 0%, 170% 0%, 0% 170%);
}

.__UIV_SCOPE__ .card .card-1:has(~ .card-2:hover),
.__UIV_SCOPE__ .card .card-1:has(~ .card-3:hover) {
  clip-path: polygon(0% 0%, 15% 0%, 0% 15%);
}

.__UIV_SCOPE__ .card .card-2 {
  z-index: 0;
}

.__UIV_SCOPE__ .card .card-3 {
  clip-path: polygon(25% 100%, 100% 25%, 100% 100%);
}

.__UIV_SCOPE__ .card .card-3:hover {
  clip-path: polygon(-70% 100%, 100% -70%, 100% 100%);
}

.__UIV_SCOPE__ .card .card-1:hover ~ .card-3,
.__UIV_SCOPE__ .card .card-2:hover ~ .card-3 {
  clip-path: polygon(85% 100%, 100% 85%, 100% 100%);
}

/*Optional styles*/
.__UIV_SCOPE__ .card {
  font: 30px Arial, Helvetica, sans-serif;
}

.__UIV_SCOPE__ .card > .child {
  /*If using background image on card children*/
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  transition: all 0.6s;
}

.__UIV_SCOPE__ .card .card-1 {
  background-color: #23a;
  color: white;
  padding-top: 30%;
  padding-left: 20%;
}

.__UIV_SCOPE__ .card .card-1:hover {
  padding-top: 65%;
  padding-left: 48%;
}

.__UIV_SCOPE__ .card .card-2 {
  padding-top: 65%;
  padding-left: 48%;
  background-color: #f16;
}

.__UIV_SCOPE__ .card .card-3 {
  padding-top: 100%;
  padding-left: 76%;
  background-color: #dd2;
}

.__UIV_SCOPE__ .card .card-3:hover {
  padding-top: 65%;
  padding-left: 48%;
}
